e","name":"Wyoming"}},{"@type":"City","name":"Jackson","containedInPlace":{"@type":"State","name":"Wyoming"}},{"@type":"City","name":"Cody","containedInPlace":{"@type":"State","name":"Wyoming"}},{"@type":"City","name":"Rawlins","containedInPlace":{"@type":"State","name":"Wyoming"}}],"priceRange":"$$","knowsAbout":["Insurance appraisal","Appraisal clause","Hail damage","Wind damage","Snow load","Xactimate estimating","Umpire services"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://wyominginsuranceappraiser.com/#website","url":"https://wyominginsuranceappraiser.com/","name":"Wyoming Insurance Appraiser","publisher":{"@id":"https://wyominginsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://wyominginsuranceappraiser.com/claim-terms/#webpage","url":"https://wyominginsuranceappraiser.com/claim-terms/","name":"Insurance Claim Terms Glossary | ACV, RCV, Umpire & More","description":"A searchable glossary of property insurance claim terms: actual cash value, holdback, test squares, umpires, matching, O&P and more, in plain English.","inLanguage":"en-US","isPartOf":{"@id":"https://wyominginsuranceappraiser.com/#website"},"about":{"@id":"https://wyominginsuranceappraiser.com/#business"},"publisher":{"@id":"https://wyominginsuranceappraiser.com/#business"},"dateModified":"2026-11-11","primaryImageOfPage":{"@type":"ImageObject","url":"https://wyominginsuranceappraiser.com/assets/img/photos/financial-calculator.webp","width":1200,"height":749},"breadcrumb":{"@id":"https://wyominginsuranceappraiser.com/claim-terms/#breadcrumb"},"mainEntity":{"@id":"https://wyominginsuranceappraiser.com/claim-terms/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://wyominginsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim terms","item":"https://wyominginsuranceappraiser.com/claim-terms/"}],"@id":"https://wyominginsuranceappraiser.com/claim-terms/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim terms","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"The value of damaged property at the time of loss, usually replacement cost minus depreciation."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while your home is uninhabitable after a covered loss."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision, signed by any two of the three panel members, that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side names to value the loss on an appraisal panel; usually required to be competent and independent."},{"@type":"DefinedTerm","name":"Bad faith","description":"A legal claim that an insurer unreasonably handled or denied a claim. Decided by courts, not appraisal panels."},{"@type":"DefinedTerm","name":"Class 4 shingle","description":"A shingle rated for the highest impact resistance under the UL 2218 test; common in hail-prone Wyoming towns."},{"@type":"DefinedTerm","name":"Collapse","description":"A coverage term, defined in each policy, for the sudden falling in of a building or part of one, such as from snow weight."},{"@type":"DefinedTerm","name":"Cosmetic damage exclusion","description":"An endorsement that excludes damage that changes appearance but not function, often applied to dented metal roofing."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage — the limit for the house itself and attached structures."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached garages, shops, barns and fences."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property, or contents, coverage."},{"@type":"DefinedTerm","name":"Creased shingle","description":"A shingle bent back by wind so that it has lost its seal and much of its wind resistance."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing limits, deductibles, endorsements and the insured property."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition, subtracted from replacement cost to reach actual cash value."},{"@type":"DefinedTerm","name":"Disinterested","description":"Having no financial stake in the outcome; a requirement many policies place on appraisers."},{"@type":"DefinedTerm","name":"Endorsement","description":"A form that adds to, removes or changes the terms of a base policy."},{"@type":"DefinedTerm","name":"Estimate review","description":"A line-by-line check of an insurance estimate for missing items, measurement errors and pricing issues."},{"@type":"DefinedTerm","name":"Ground snow load","description":"The design weight of snow on the ground at a location, used by building codes to set roof load requirements."},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation withheld from the first payment until repairs are completed."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can back up under shingles and leak inside."},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering waterproof underlayment installed at eaves and valleys, often required by code in snowy areas."},{"@type":"DefinedTerm","name":"Line item","description":"A single priced entry in an estimate, such as a quantity of shingles or a square foot of drywall."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether replacement materials must reasonably match undamaged materials in color and style."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, like tarping a roof or extracting water."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for extra costs to bring repaired portions of a building up to current code."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge, often 10% plus 10%, for coordinating multiple trades on a repair."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of Coverage A rather than a flat dollar amount; common for wind and hail."},{"@type":"DefinedTerm","name":"Pitch","description":"The steepness of a roof, expressed as inches of rise per 12 inches of run, such as 6/12."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which an insurer may require within a set time after requesting it."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation that can be collected after repairs are completed under a replacement cost policy."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deduction for depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which an insurer continues to handle a claim while reserving the right to deny coverage later."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The full list of damaged items and the work needed to repair them."},{"@type":"DefinedTerm","name":"Square","description":"A roofing unit equal to 100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Steep charge","description":"An estimate line adding labor cost for roofs too steep to walk safely, usually 7/12 pitch and above."},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy condition setting how long you have to file a lawsuit against the insurer."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add missing or underpriced items to an existing insurance estimate."},{"@type":"DefinedTerm","name":"Surplus lines","description":"Coverage placed with insurers not licensed as admitted carriers in a state, used for risks standard insurers won’t write."},{"@type":"DefinedTerm","name":"Test square","description":"A 10-by-10-foot area marked on a roof slope where hail hits are counted."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Wind-driven hail","description":"Hail carried at an angle by strong wind, which damages siding, windows and windward roof slopes."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers, adjusters and contractors to price property repairs."}],"@id":"https://wyominginsuranceappraiser.com/claim-terms/#definedtermset"}]}</script>
</head>
